-- Generated English/Japanese draft translations for the exact local-eum-dev snapshot.
-- Target project: rhkaxmqdkztpbljkunxb
-- Applied after the user requested database localization. Every locale remains DRAFT for host review.
-- This script updates only translations on the two existing hosts, twelve existing experiences,
-- and fifty existing itinerary rows. available_languages stays empty until each host confirms it.

begin;
set local lock_timeout = '5s';

do $$
begin
  if to_regclass('public.lc_hosts') is null
    or to_regclass('public.lc_experiences') is null
    or to_regclass('public.lc_experience_steps') is null then
    raise exception 'Expected Local Eum tables are missing; abort translation update';
  end if;
  if (select count(*) from public.lc_hosts where host_id in (500, 501)) <> 2
    or (select count(*) from public.lc_experiences where is_demo and status='PUBLISHED' and demo_code like 'DEMO-%') <> 12
    or (select count(*) from public.lc_experience_steps where experience_id between 101 and 112) <> 50 then
    raise exception 'Unexpected host, published experience, or itinerary count; abort translation update';
  end if;
  if (select count(*) from public.lc_experiences where host_id=500 and experience_id between 101 and 110) <> 10
    or (select count(*) from public.lc_experiences where host_id=501 and experience_id in (111,112)) <> 2
    or (select count(*) from public.lc_experiences where experience_id between 101 and 112 and
      ((experience_id between 101 and 110 and host_id<>500) or (experience_id in (111,112) and host_id<>501))) <> 0 then
    raise exception 'Host ownership differs from the approved 500/501 mapping; abort translation update';
  end if;
  if not exists (select 1 from public.lc_hosts where host_id=500 and display_name='로컬이음 체험 호스트'
      and md5(bio)='505dde75d6239902647f53f903e854c7')
    or not exists (select 1 from public.lc_hosts where host_id=501 and display_name='마산 골목 이야기'
      and md5(bio)='472ffac5642291d911425a7abfc365f4') then
    raise exception 'Host source text changed since translation review; abort';
  end if;
end $$;

do $$
declare changed integer;
begin
  with payload(host_id, display_name, source_bio_md5, en, ja) as (values
    (500::bigint, '로컬이음 체험 호스트'::text, '505dde75d6239902647f53f903e854c7'::text,
      $en${"bio":"**Finding the warmth of familiar people in an unfamiliar destination**\n\nHello, I am a Local Eum host who introduces new sides of a destination and meaningful encounters with local people.\n\nI believe a trip is about more than visiting famous places. A story discovered by chance in a neighborhood alley, a brief conversation at a market, or a moment spent learning about another culture can stay with us for a long time.\n\nI create participatory programs for travelers in places such as Seoul, Busan, and Changwon.\n\nWe explore markets and alleyways, learn about local culture, and share our interests and stories.\n\n**I will help connect you with experiences that turn a simple visit into a lasting memory.**","review_status":"DRAFT"}$en$::jsonb,
      $ja${"bio":"**旅先で出会う、親しみのある人の温もり**\n\nこんにちは。旅先の新しい表情や、地域の人との特別な出会いをご紹介するローカルイウムのホストです。\n\n旅は有名な場所を訪れるだけで完成するものではないと思います。路地で偶然見つけた物語、市場で交わした短い会話、異なる文化を知るひとときが、長く心に残ることもあります。\n\nソウル、釜山、昌原などを舞台に、旅行者が参加して体験できるプログラムをご紹介します。\n\n市場や路地を歩き、地域の文化を学び、好きなことや物語を語り合う時間をお届けします。\n\n**旅がただの訪問ではなく、特別な思い出になるよう、人と体験をつなぎます。**","review_status":"DRAFT"}$ja$::jsonb),
    (501::bigint, '마산 골목 이야기'::text, '472ffac5642291d911425a7abfc365f4'::text,
      $en${"bio":"I am a local host who helps travelers experience Masan’s old alleys and markets in new ways. I create opportunities to discover special stories in familiar neighborhoods through missions and activities that invite travelers to take part.\n\nActivity area: Masanhappo-gu, Changwon-si, Gyeongsangnam-do.","review_status":"DRAFT"}$en$::jsonb,
      $ja${"bio":"馬山の古い路地や市場を、新しい方法で体験するお手伝いをするローカルホストです。旅人が参加できるミッションや活動を通して、見慣れた街の中にある特別な物語を見つける機会をつくります。\n\n活動地域：慶尚南道・昌原市・馬山合浦区。","review_status":"DRAFT"}$ja$::jsonb)
  ), updated as (
    update public.lc_hosts h set translations = coalesce(h.translations, '{}'::jsonb)
      || jsonb_build_object('en', p.en || coalesce(h.translations->'en', '{}'::jsonb),
                            'ja', p.ja || coalesce(h.translations->'ja', '{}'::jsonb))
    from payload p where h.host_id=p.host_id and h.display_name=p.display_name and md5(h.bio)=p.source_bio_md5
    returning h.host_id
  ) select count(*) into changed from updated;
  if changed <> 2 then raise exception 'Expected to update 2 host translations, updated %; abort', changed; end if;
end $$;

do $$
declare changed integer;
begin
  with payload(experience_id, host_id, demo_code, title, source_updated_at, en, ja) as (values
    (101::bigint,500::bigint,'DEMO-04','광장시장 음식문화 산책','2026-10-17T02:04:51.796038+00:00'::timestamptz,
      $en${"title":"Gwangjang Market Food Culture Walk","description":"Explore the flavors of a traditional market together.","detail_description":"A sample walk that connects an introduction to Gwangjang Market with its food culture, using the real market address as a setting. The route and schedule are for demonstration only. They do not represent an agreement with the merchants’ association or any individual shop, and the fee does not guarantee food, coin vouchers, or tastings.","inclusions":["Demo setup: route guidance and a sample itinerary"],"preparation_items":["Suggested for the demo: comfortable walking shoes","Suggested for the demo: personal water and clothing suitable for the season"],"precautions":["All schedules, fees, capacities, and inclusions are development demo settings; they do not indicate actual bookings or operating agreements with venues.","Food purchases and tastings are not confirmed inclusions.","The sample route assumes that market access remains clear and does not obstruct merchants or visitors."],"review_status":"DRAFT"}$en$::jsonb,
      $ja${"title":"広蔵市場の食文化散策","description":"伝統市場の味を一緒に巡りながら楽しむ体験です。","detail_description":"広蔵市場の実際の住所を舞台に、市場の紹介と食文化をつなぐ散策のサンプルです。ルートと日程はデモ用であり、商店会や個別店舗との合意を示すものではありません。参加費に食べ物、コイン券、試食が含まれることも保証されません。","inclusions":["デモ設定：ルート案内と日程表の例"],"preparation_items":["デモの推奨持ち物：歩きやすい靴","デモの推奨持ち物：飲み水と季節に合った服装"],"precautions":["日程、参加費、定員、提供内容はすべて開発用デモ設定です。実際の予約や施設との運営契約を示すものではありません。","食べ物の購入や試食は確定した提供内容ではありません。","商店や来場者の通行を妨げないデモ用ルートを想定しています。"],"review_status":"DRAFT"}$ja$::jsonb),
    (102,500,'DEMO-01','성수동 공방 체험','2026-10-17T01:56:28.065764+00:00',
