      $en${"title":"Today’s Seafood Table Lab","description":"A demo food experience exploring seasonal ingredients and food culture at Masan Fish Market, with a planned tasting comparison and a personal seafood table card.","detail_description":"Today’s Seafood Table Lab is a concept for observing seasonal ingredients and learning about food culture at Masan Fish Market. A comparison tasting and a personalized seafood table card may be considered if a partner is confirmed. The tasting partner, venue, costs, hygiene arrangements, and allergen information are not yet confirmed, so no food is served and real bookings or payments are disabled. All schedules and prices are development demo estimates.","inclusions":["Ingredient exploration card (demo concept)","Personal food discovery card (demo concept)"],"preparation_items":["Comfortable walking shoes","Personal note-taking supplies"],"precautions":["Demo only · Real bookings and payments are unavailable.","Tasting partner, location, costs, hygiene arrangements, and allergen information are not confirmed.","Before any real operation, coordinate with merchants and confirm safe food-service procedures."],"review_status":"DRAFT"}$en$::jsonb,
      $ja${"title":"今日の海の幸テーブル研究所","description":"馬山魚市場で旬の食材と食文化を探り、試食比較や自分好みの海鮮テーブルカードを企画するデモ用グルメ体験です。","detail_description":"「今日の海の幸テーブル研究所」は、馬山魚市場で旬の食材を観察し、食文化を学ぶ企画です。協力先が決まった場合に、食べ比べと個人別の海鮮テーブルカードを検討します。試食の協力先、場所、費用、衛生管理、アレルギー情報は未確定のため、食品の提供は行わず、実際の予約・決済も無効です。日程と料金はすべて開発用デモの案です。","inclusions":["食材探究カード（デモ企画）","個人別グルメカード（デモ企画）"],"preparation_items":["歩きやすい靴","個人用の筆記用具"],"precautions":["デモ用・実際の予約と決済はできません。","試食の協力先、場所、費用、衛生管理、アレルギー情報は未確定です。","実際に運営する前に、商店との調整と食品提供方法の確認が必要です。"],"review_status":"DRAFT"}$ja$::jsonb),
    (112,501,'DEMO-MASAN-MYSTERY-MAP','사라진 마산의 비밀지도','2026-10-17T04:53:40.119448+00:00',
      $en${"title":"Masan’s Missing Secret Map","description":"A host-led outdoor mystery game in Changdong’s old downtown, where teams solve clues and complete their own map.","detail_description":"In the fictional case “The Last Color of Three Alleys,” participants complete a blank map left by an imaginary mapmaker named Yunseo. Cards distinguish verified local information from the fictional story. The host provides a detective kit and clues; participants walk through public alleys in Changdong Art Village and around Burim Market to observe, reason, and collaborate. The route does not require entering shops, making purchases, touching facilities, placing markers, or photographing people. This is a demo experience and does not accept real bookings.","inclusions":["Detective kit and clue cards (demo concept)","Team-completed map card","Completion card"],"preparation_items":["Comfortable walking shoes","Pen or pencil"],"precautions":["Demo only · Real bookings and payments are unavailable.","Keep fictional case details distinct from verified local facts.","Do not enter shops, request purchases, touch facilities, place unauthorized markers, or photograph people.","Confirm the walking route and a rainy-weather alternative after an on-site visit."],"review_status":"DRAFT"}$en$::jsonb,
      $ja${"title":"馬山・消えた秘密の地図","description":"昌洞の旧市街で手がかりを解き、チーム独自の地図を完成させるホスト進行型の屋外ミステリーゲームです。","detail_description":"架空の事件「三つの路地に残された最後の色」は、想像上の地図制作者ユンソが残した白地図を参加者が完成させる物語です。カード上で、確認された地域情報と創作上の設定を区別します。ホストが探偵キットと手がかりを用意し、参加者は昌洞芸術村の公開路地や富林市場周辺を歩きながら観察・推理・チーム協力を行います。店舗への立ち入りや購入、施設への接触、目印の設置、人の撮影は行いません。デモ用体験であり、実際の予約は受け付けません。","inclusions":["探偵キットと手がかりカード（デモ企画）","チーム完成地図カード","完走カード"],"preparation_items":["歩きやすい靴","筆記用具"],"precautions":["デモ用・実際の予約と決済はできません。","架空の事件設定と確認済みの地域情報を区別してください。","店舗への立ち入りや購入の要求、施設への接触、無断の目印設置、人の撮影は禁止です。","現地確認後に歩行ルートと雨天時の代替案を確定してください。"],"review_status":"DRAFT"}$ja$::jsonb)
  ), updated as (
    update public.lc_experiences e set translations = coalesce(e.translations, '{}'::jsonb)
      || jsonb_build_object('en', p.en || coalesce(e.translations->'en', '{}'::jsonb),
                            'ja', p.ja || coalesce(e.translations->'ja', '{}'::jsonb))
    from payload p where e.experience_id=p.experience_id and e.host_id=p.host_id
      and e.demo_code=p.demo_code and e.title=p.title and e.updated_at=p.source_updated_at
    returning e.experience_id
  ) select count(*) into changed from updated;
  if changed <> 12 then raise exception 'Expected to update 12 experience translations, updated %; abort', changed; end if;
end $$;

