    (49,111,1,'미식 미션 안내','2026-10-17T04:53:40.119448+00:00',$en${"title":"Food discovery mission briefing","description":"At a public pedestrian area, review the ground rules, ingredient exploration card, and allergy-check process. No tasting is offered until a partner is confirmed.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"食の探究ミッション案内","description":"公共の歩行エリアで進行ルール、食材探究カード、アレルギー確認の手順を案内します。協力先が確定するまで試食は提供しません。","review_status":"DRAFT"}$ja$::jsonb),
    (50,111,2,'제철 식재료 관찰','2026-10-17T04:53:40.119448+00:00',$en${"title":"Observe seasonal ingredients","description":"Without interrupting sales, observe seasonality, color, and origin information, then sort the findings on a card.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"旬の食材を観察","description":"販売の妨げにならないよう、食材の季節性・色・産地情報を観察し、カードに分類します。","review_status":"DRAFT"}$ja$::jsonb),
    (51,111,3,'음식 비교 시식 기획','2026-10-17T04:53:40.119448+00:00',$en${"title":"Plan a comparative tasting","description":"A small comparison of two or three items may take place only after merchant cooperation, hygiene, and allergy conditions are approved. For now, this is explained as a demo concept.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"食べ比べを企画","description":"商店の協力、衛生管理、アレルギー対応が承認された場合に限り、2～3品の少量食べ比べを行います。現在はデモ企画として説明のみ行います。","review_status":"DRAFT"}$ja$::jsonb),
    (52,111,4,'나만의 바다밥상 구성','2026-10-17T04:53:40.119448+00:00',$en${"title":"Create your own seafood table","description":"Use the menu card to design a seafood table that reflects each participant’s preferences.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"自分だけの海鮮テーブルを作る","description":"メニューカードを使い、参加者それぞれの好みに合わせた海鮮の食卓を組み立てます。","review_status":"DRAFT"}$ja$::jsonb),
    (61,111,5,'미식 카드와 마무리','2026-10-17T04:53:40.119448+00:00',$en${"title":"Food discovery card and wrap-up","description":"Record a favorite ingredient and the reason on a personal food discovery card, then wrap up.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"グルメカードとまとめ","description":"好きな食材とその理由を個人用グルメカードに記録し、終了します。","review_status":"DRAFT"}$ja$::jsonb),
    (53,112,1,'사건 접수와 키트 배부','2026-10-17T04:53:40.119448+00:00',$en${"title":"Open the case and hand out the kits","description":"Participant task: inspect the blank map left by the fictional mapmaker Yunseo and learn the observation rules. Host role: explain that the case is fictional, cover safety, photography, and shop-access rules, and hand out the team record sheet and pencils. Team output: a record sheet and assigned roles.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"事件受付とキット配布","description":"参加者の課題：架空の地図制作者ユンソが残した白地図を確認し、観察ルールを学びます。ホストの役割：架空の事件であることを説明し、安全・撮影・店舗立ち入りのルールを案内して、チーム記録用紙と鉛筆を配ります。成果物：チーム記録用紙と役割分担。","review_status":"DRAFT"}$ja$::jsonb),
    (54,112,2,'세 테마 골목 첫 단서','2026-10-17T04:53:40.119448+00:00',$en${"title":"First clue: the three themed alleys","description":"Question: using the official Changdong Art Village guide map and alley cards, find how many themes the alleys are divided into and write the number. The host supplies the official guide or a prepared fallback card. Team output: the first numeric clue and its source.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"三つのテーマ路地・最初の手がかり","description":"問題：昌洞芸術村の公式案内地図と路地カードを使い、路地がいくつのテーマに分かれているかを調べて数字で記入します。ホストは公式案内地図、または代替カードを用意します。成果物：最初の数字の手がかりと確認した根拠。","review_status":"DRAFT"}$ja$::jsonb),
    (55,112,3,'골목 이름과 관찰 암호','2026-10-17T04:53:40.119448+00:00',$en${"title":"Alley name and observation code","description":"Question: use the mapmaker’s name clue and the official-name card to identify the target alley. In a public pedestrian area, observe one feature—color, line, or repetition—and record the evidence. The host gives step-by-step hints without revealing the answer and watches for safe walking and private-property boundaries. Team output: the alley-name clue, a chosen observation symbol, and the reason for choosing it. Allow extra time for walking between locations.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"路地名と観察コード","description":"問題：地図制作者が残した名前の手がかりと正式名称カードから対象の路地を見つけます。公共の歩行エリアで色・線・反復のいずれか一つを観察し、根拠を記録します。ホストは答えをすぐに明かさず段階的なヒントを出し、安全な歩行と私有地との境界に注意します。成果物：路地名の手がかり、チームが選んだ観察記号とその理由。移動時間も含めます。","review_status":"DRAFT"}$ja$::jsonb),
    (56,112,4,'부림시장 마지막 좌표','2026-10-17T04:53:40.119448+00:00',$en${"title":"Final location clue: Burim Market","description":"Question: find the final place name on a printed map or a public sign that can be safely checked, and write it on the clue card. If the sign is hard to see or the area is crowded, the host switches to a printed map and manages pedestrian and vehicle flow. Team output: the final location clue and the team’s completed code.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"富林市場・最後の場所の手がかり","description":"問題：印刷地図、または安全に確認できる公開標識から最後の場所の名前を見つけ、手がかりカードに記録します。標識が見えにくい場合や混雑時は、ホストが印刷地図に切り替え、歩行者と車両の通行に配慮します。成果物：最後の場所の手がかりとチームの最終コード。","review_status":"DRAFT"}$ja$::jsonb),
    (66,112,5,'지도 완성과 사건 해결','2026-10-17T04:53:40.119448+00:00',$en${"title":"Complete the map and solve the case","description":"Participant task: connect the locations and observed features on the blank map and present why the team made each discovery. Host role: distinguish verified fact cards from fictional story elements again and hand out completion cards. Team output: a completed map card and a completion card.","review_status":"DRAFT"}$en$::jsonb,$ja${"title":"地図を完成させ事件を解決","description":"参加者の課題：見つけた場所と実際に観察した特徴を白地図上で結び、発見の理由を発表します。ホストの役割：確認済みの事実カードと創作設定を改めて区別し、完走カードを渡します。成果物：チーム完成地図カードと完走カード。","review_status":"DRAFT"}$ja$::jsonb)
  ), updated as (
    update public.lc_experience_steps s set translations = coalesce(s.translations, '{}'::jsonb)
      || jsonb_build_object('en', p.en || coalesce(s.translations->'en', '{}'::jsonb),
                            'ja', p.ja || coalesce(s.translations->'ja', '{}'::jsonb))
    from payload p where s.step_id=p.step_id and s.experience_id=p.experience_id
      and s.step_order=p.step_order and s.title=p.title and s.updated_at=p.source_updated_at
    returning s.step_id
  ) select count(*) into changed from updated;
  if changed <> 50 then raise exception 'Expected to update 50 itinerary translations, updated %; abort', changed; end if;
end $$;

do $$
begin
  if (select count(*) from public.lc_hosts where host_id in (500,501)
      and translations ? 'en' and translations ? 'ja'
      and translations->'en'->>'review_status'='DRAFT'
      and translations->'ja'->>'review_status'='DRAFT') <> 2 then
    raise exception 'Host translations did not pass post-check';
  end if;
  if (select count(*) from public.lc_experiences where experience_id between 101 and 112
      and translations ? 'en' and translations ? 'ja'
      and translations->'en'->>'review_status'='DRAFT'
      and translations->'ja'->>'review_status'='DRAFT') <> 12 then
    raise exception 'Experience translations did not pass post-check';
  end if;
  if (select count(*) from public.lc_experience_steps where experience_id between 101 and 112
      and translations ? 'en' and translations ? 'ja'
      and translations->'en'->>'review_status'='DRAFT'
      and translations->'ja'->>'review_status'='DRAFT') <> 50 then
    raise exception 'Itinerary translations did not pass post-check';
  end if;
  if (select count(*) from public.lc_experiences where host_id=500 and experience_id between 101 and 110) <> 10
    or (select count(*) from public.lc_experiences where host_id=501 and experience_id in (111,112)) <> 2
    or (select count(*) from public.lc_experiences where experience_id between 101 and 112 and
      ((experience_id between 101 and 110 and host_id<>500) or (experience_id in (111,112) and host_id<>501))) <> 0 then
    raise exception 'Host ownership changed during translation update';
  end if;
  if (select count(*) from public.lc_experiences where experience_id between 101 and 112 and cardinality(available_languages)=0) <> 12 then
    raise exception 'Host-confirmed delivery languages changed unexpectedly';
  end if;
end $$;

commit;
